// spec: .qa/e2e/specs/admin-content.md 1.3 · тикет #686cecdc (AC 8, 14, 17)
// Две роли (пишется вручную): user4 публикует пост «QA-AUTO …» (тем же запросом, что приложение) → admin в «כל התוכן»
// снимает его: окно подтверждения, сначала сбой сервера (ответ server action подменён на 500) → «אין חיבור. נסו שוב»,
// затем удаление по-настоящему → «הפוסט הוסר», пост в «הוסר», автор его больше не видит.
// @data: снятый пост остаётся в «הוסר» (в админке нет «вернуть»), у user4 +1 к «תוכן שהוסר ב־30 יום». Уведомление автору выключено.
// Если тест оборвался до снятия — пост удаляет сам user4 (finally).
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { ADMIN_URL, adminAs, appApi, cId, closeAdmin, closeApp, contentDetail, contentQueue, createPost, deletePost, iphoneAs, postVisibleToAuthor, qaText } from '../moderation-menu/mod-helpers';
import type { Api } from '../_shared/api';

test.describe('מסך ניהול תוכן — снятие', () => {
  test('Снятие поста: «להסיר את הפוסט?» с причиной; сбой сервера — «אין חיבור. נסו שוב»; затем «הפוסט הוסר», пост в «הוסר» и пропал у автора @desktop @data (#686cecdc)', async ({ browser }) => {
    test.setTimeout(150_000);
    const user = await iphoneAs(browser, 'user4');
    let admin: Page | undefined;
    let api: Api | undefined;
    let id = '';
    let removed = false;
    const text = qaText('686cecdc', 'remove');
    try {
      api = await appApi(user);
      id = await createPost(api, text);

      admin = await adminAs(browser);
      await admin.goto(`${ADMIN_URL}/content?tab=all&q=${encodeURIComponent(text)}`);
      const row = contentQueue(admin).getByRole('link', { name: new RegExp(cId(id)) });
      await expect(row).toContainText(text);
      await expect(row).toContainText('פוסט · פיד');
      await row.click();
      await expect(admin).toHaveURL(new RegExp(`id=${id}`));
      const detail = contentDetail(admin);
      await expect(detail.getByText(text, { exact: true })).toBeVisible();

      // Окно подтверждения (AC 14)
      await detail.getByRole('button', { name: 'הסרת הפוסט' }).click();
      const dlg = admin.getByRole('dialog').filter({ hasText: 'להסיר את הפוסט?' });
      await expect(dlg).toBeVisible();
      await expect(dlg.getByRole('radiogroup', { name: 'סיבת ההסרה' })).toBeVisible();
      for (const r of ['מילים אסורות', 'תוכן פוגעני', 'ספאם']) await expect(dlg.getByRole('radio', { name: r })).toBeVisible();
      const notify = dlg.getByRole('checkbox', { name: /^לשלוח התראה ל/ });
      if (await notify.isChecked()) await dlg.getByText(/^לשלוח התראה ל/).click();
      await expect(notify).not.toBeChecked();

      // Сбой (AC 17): server action удаления отвечает 500
      await admin.route(
        (u) => u.pathname === '/content',
        (route) => (route.request().method() === 'POST' ? route.fulfill({ status: 500, body: 'qa-error' }) : route.continue()),
      );
      await dlg.getByRole('button', { name: 'הסרת הפוסט' }).click();
      await expect(dlg.getByRole('alert')).toContainText('אין חיבור. נסו שוב');
      await expect(dlg).toBeVisible();
      expect(await postVisibleToAuthor(api, id), 'после сбоя пост не снят').toBe(true);
      await admin.unrouteAll({ behavior: 'ignoreErrors' });

      // Снятие по-настоящему (AC 8)
      const action = admin.waitForResponse((r) => r.request().method() === 'POST' && new URL(r.url()).pathname === '/content');
      await dlg.getByRole('button', { name: 'הסרת הפוסט' }).click();
      const res = await action;
      expect(res.ok(), 'server action снятия').toBeTruthy();
      expect(res.request().postData() ?? '').toContain(id);
      removed = true;
      await expect(admin.getByRole('status').filter({ hasText: 'הפוסט הוסר' })).toBeVisible();

      // В «הוסר» с пометкой «הוסר»; у автора поста больше нет
      await admin.goto(`${ADMIN_URL}/content?tab=removed&q=${encodeURIComponent(text)}`);
      const removedRow = contentQueue(admin).getByRole('link', { name: new RegExp(cId(id)) });
      await expect(removedRow).toContainText('הוסר');
      await removedRow.click();
      await expect(contentDetail(admin).getByText('הוסר על ידי מנהל/ת').first()).toBeVisible();
      await expect.poll(() => postVisibleToAuthor(api!, id)).toBe(false);
      await user.goto('/social');
      await expect(user.getByRole('button', { name: 'פוסט חדש' })).toBeVisible({ timeout: 30_000 }); // сплэш приложения
      await expect(user.getByText(text, { exact: true })).toHaveCount(0);
    } finally {
      if (api && id && !removed) await deletePost(api, id);
      await closeAdmin(admin);
      await closeApp(user, 'user4');
    }
  });
});
